button_details.script:
					function onButtonPress()
            local sDBnode = window.getDatabaseNode();
            sf.DebugOut("DB Node: " .. sDBnode.getPath());

            local sRuleset = Interface.getRuleset();
            sf.DebugOut("Using ruleset: " .. sRuleset, true);

            Interface.openWindow("charsheet_abilityboost_sfrpg", sDBnode);
					end

state_charammocounter.script:
        function onValueChanged()
          local sDBnode = window.getDatabaseNode();
          Debug.console("Ammo Counter DB Node: " .. sDBnode.getPath());

          local nCount = DB.getValue(sDBnode, "ammo",0);
          Debug.console("Ammo Counter changed to: " .. nCount);

          checkInventory();
        end
        function checkInventory()
          local sDBnode = window.getDatabaseNode();
          local sWeaponNode = DB.getValue(sDBnode, "subtype","");

          if sWeaponNode == "grenade" or sWeaponNode == "Grenade" then
            Debug.console("Grenade used; checking if we can find its ammo count from the linked item from inventory list");
            -- shortcut.recordname == ....inventorylist.id-00001
            local sWeaponNode = DB.getChild(sDBnode, "shortcut.recordname");
            Debug.console("checkInventory: sWeaponNode: " .. sWeaponNode);

          else
            Debug.console("checkInventory: not a grenade; " .. sWeaponNode);
          end
        end
